# Generated by the start-bridge codemod for chat; re-run it instead of editing.
"""Validate and preserve the chat staging artifact; never deploy.

Reuses the reviewed Apps seal/restore implementation with this app's Worker
identity, public files and source-SHA channel.
"""
import importlib.util
import os
from pathlib import Path

PROFILE = os.environ.get("VITE_CHAT_NATIVE_PROFILE", "staging")
if PROFILE not in ("staging", "production"):
    raise ValueError("Unknown chat native profile")
WORKER = "tuturuuu-chat" if PROFILE == "production" else "tuturuuu-chat-vite-staging"
# Chat ships robots.txt only. The Apps seal compares each listed file with
# apps/chat/public, so a copied sitemap entry fails the seal.
PUBLIC_FILES = ("robots.txt",)


def load():
    path = Path(__file__).with_name("apps-native-artifact.py")
    spec = importlib.util.spec_from_file_location("chat_native_artifact_base", path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    module.IDENTITY = {
        **module.IDENTITY,
        "name": WORKER,
        "vars": {"TUTURUUU_NOINDEX": "0" if PROFILE == "production" else "1"},
        "compatibility_date": "2026-10-12",
        "compatibility_flags": ["nodejs_compat","global_fetch_strictly_public"],
        "workers_dev": False,
        "preview_urls": False,
    }
    module.NORMALIZED_DEFAULTS = {**module.NORMALIZED_DEFAULTS, "topLevelName": WORKER}
    module.RECEIPT = "chat-native-artifact.json"
    module.PUBLIC_FILES = PUBLIC_FILES
    return module


def main():
    # The shared CLI reads its exact source from APPS_SOURCE_SHA.
    if "CHAT_SOURCE_SHA" in os.environ:
        os.environ["APPS_SOURCE_SHA"] = os.environ["CHAT_SOURCE_SHA"]
    else:
        os.environ.pop("APPS_SOURCE_SHA", None)
    load().main()


if __name__ == "__main__":
    main()
